// GENERATED by `python3 -m transcribr.contract` - do not edit.
//
// Python owns these shapes (settings defaults and their
// validation, the palettes, the run phases), so they are
// generated from it rather than declared twice. Change them in
// Python and regenerate; test_contract.py fails if this file is
// stale.

/** Same keys and value conventions as settings.json. */
export interface Settings {
  engine: string;
  model: string;
  language: string;
  task: "transcribe" | "translate";
  output_format: "txt" | "docx" | "pdf";
  /** Word layout: plain, court (numbered lines, double spaced, running
   *  header) or erisp (record-of-interview heading, numbered lines).
   */
  doc_template: "plain" | "court" | "erisp";
  /** Offer [indistinct] in review for passages the engine was unsure of.
   *  Never applied without the reviewer.
   */
  offer_indistinct: boolean;
  /** Document title (heading). Never sent to the engine. */
  title: string;
  /** Optional initial_prompt / vocabulary hint. Opt-in; can backfire. */
  prompt: string;
  /** Start a new paragraph after a silence of this many seconds. */
  gap: number;
  show_timestamp: boolean;
  /** Shade each speaker's paragraphs in .docx/.pdf with the review pane's
   *  colours. Plain text has nowhere to put a colour.
   */
  colour_speakers: boolean;
  temperature: number;
  beam_size: number;
  best_of: number;
  compression_ratio_threshold: number;
  logprob_threshold: number;
  no_speech_threshold: number;
  condition_on_previous_text: boolean;
  extra_json: boolean;
  extra_srt: boolean;
  extra_vtt: boolean;
  extra_tsv: boolean;
  theme: "auto" | "light" | "dark";
  show_details: boolean;
  diarize: boolean;
  num_speakers: number;
  diarize_model: string;
  diarize_threshold: number;
  show_all_models: boolean;
  /** Show the context/vocabulary priming field on the Transcribe page. */
  show_prompt: boolean;
  /** Word-level timing & confidence highlighting. */
  word_timestamps: "auto" | "on" | "off";
  /** Show the experimental speaker-detection card on the Transcribe page. */
  show_diarize: boolean;
  check_updates: boolean;
  /** Re-run the sections that look like engine error before the review
   *  pane opens.
   */
  auto_retranscribe: boolean;
  /** Feed confirmed names back to the engine as context. Off by default:
   *  priming can make the engine hear a name where none was said.
   */
  prime_with_terms: boolean;
  /** Start a new paragraph where the voice changes pitch sharply after a
   *  finished sentence - usually a new speaker.
   */
  voice_breaks: boolean;
}

export type ThemeSetting = "auto" | "light" | "dark";

/** Transcript-semantic colours served from Python's _PALETTES. */
export interface Palette {
  text_bg: string;
  text_fg: string;
  insert: string;
  speaker_fg: string;
  timestamp_fg: string;
  selected_bg: string;
  editing_bg: string;
  search_bg: string;
  conf_low: string;
  conf_med: string;
  badge_fg: string;
  speaker_colours: Record<"1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9", string>;
  drop_bg: string;
  drop_hover: string;
  drop_border: string;
  drop_fg: string;
}

export type RunPhase =
  | "idle"
  | "running"
  | "stopping"
  | "done"
  | "error"
  | "cancelled";

/** The settings whose values this build fixes. */
export const SETTING_CHOICES = {
  task: ["transcribe", "translate"],
  output_format: ["txt", "docx", "pdf"],
  doc_template: ["plain", "court", "erisp"],
  theme: ["auto", "light", "dark"],
  word_timestamps: ["auto", "on", "off"],
} as const;
